<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {can,projectId} from '@/core/session'
import {ApiError,identityEpoch,onIdentityChange} from '@/core/http'
import {formatTime} from '@/core/time'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {readAutomationVersion} from './automation-editor-api'
import {automationTargetAction,automationCloudOperationText,automationCloudNode,automationCloudTransformNode,automationCloudPresentation,automationSignature,type AutomationNode} from './automation-editor-draft'
import {ExactDecimal,writePreprocessJson} from './preprocess-exact-json'
import {selectedTaskChoices} from './task-choices'
import type {AutomationLogEntry} from './automation-debug-log-api'
const props=defineProps<{automationId:string;entry:AutomationLogEntry}>(),emit=defineEmits<{denied:[cause:ApiError]}>()
const nodes=ref<AutomationNode[]>([]),names=ref(new Map<string,string>()),error=ref('')
const readable=computed(()=>can('rule:manage')),deviceLinks=computed(()=>can('device:read'))
let controller:AbortController|undefined,turn=0,alive=true
function reset(){turn++;controller?.abort();nodes.value=[];names.value=new Map();error.value=''}
function current(token:number,project:string,epoch:number){return alive&&token===turn&&project===projectId.value&&epoch===identityEpoch()&&readable.value}
async function load(){reset();if(!readable.value)return;const token=turn,project=projectId.value,epoch=identityEpoch();controller=new AbortController();const signal=controller.signal
 try{const version=await readAutomationVersion(project,props.automationId,props.entry.versionId,signal);if(!current(token,project,epoch))return;nodes.value=version.actions
  if(deviceLinks.value){try{const ids=[...new Set(props.entry.actions.flatMap(row=>row.targetDeviceId?[row.targetDeviceId]:[]))].slice(0,100);if(ids.length){const rows=await selectedTaskChoices(project,'devices',ids,signal);if(current(token,project,epoch)&&deviceLinks.value)names.value=new Map(rows.map(row=>[row.id,row.label]))}}catch{/* 无名称权限时保留真实标识，不猜名称。 */}}
 }catch(cause){if(current(token,project,epoch)){error.value='原操作描述暂未读取，已记录结果保持显示。';if(cause instanceof ApiError&&[401,403].includes(cause.status))emit('denied',cause)}}}
watch([projectId,()=>props.automationId,()=>props.entry.executionId,()=>props.entry.versionId,readable,deviceLinks],()=>{void load()},{immediate:true})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;reset();dispose()})
const startedAt=computed(()=>props.entry.attempts.map(a=>a.startedAt).sort((a,b)=>Date.parse(a)-Date.parse(b))[0])
const labels={SUCCEEDED:'完成',FAILED:'失败',PENDING:'执行中',UNKNOWN:'结果未确认',SKIPPED:'跳过',BLOCKED:'被阻止'}
function valueText(value:unknown){if(value instanceof ExactDecimal){try{return writePreprocessJson(value,true)}catch{return value.canonical()}}return typeof value==='string'?value:automationSignature(value)}
const rows=computed(()=>props.entry.actions.map(action=>{const frozen=nodes.value[action.ordinal],node=frozen?.nodeType===action.nodeType?frozen:undefined,property=node&&automationTargetAction(node);return {...action,label:(action.nodeType===automationCloudNode||action.nodeType===automationCloudTransformNode)?'属性更新':action.nodeType==='automation-device-property-set-action'||action.nodeType==='device-property-set-action'?'属性下发':'操作',properties:property&&property.deviceId===action.targetDeviceId?('operations' in property?property.operations.map(row=>automationCloudOperationText(row,valueText)):Object.entries(property.properties).map(([key,value])=>`${key} ${valueText(value)}`)).join(', '):''}}))
</script>
<template><div v-if="readable" class="automation-log-timeline"><p v-if="error" class="description-error">{{error}}</p><p v-if="!entry.coverageComplete" class="coverage-note">部分操作结果尚未确认。</p>
 <el-timeline v-if="rows.length||startedAt" class="action-timeline"><el-timeline-item v-if="startedAt" color="#409eff"><div class="timeline-header"><span class="header-type">开始执行</span><span class="header-time">{{formatTime(startedAt)}}</span></div></el-timeline-item><el-timeline-item v-for="row in rows" :key="row.ordinal"><template #dot><div class="timeline-dot" :class="row.result.toLowerCase()"><ReferenceIcon :glyph="(row.nodeType===automationCloudNode||row.nodeType===automationCloudTransformNode)?automationCloudPresentation.glyph:String.fromCodePoint(0xf0552)"/></div></template><div class="timeline-content"><div class="timeline-header"><span class="header-type">{{row.label}}</span><span class="header-time">{{row.completedAt||row.acceptedAt?formatTime(row.completedAt||row.acceptedAt):'时间未知'}}</span><span class="status-icon" :class="row.result.toLowerCase()">{{labels[row.result]}}</span></div><div class="timeline-action-detail"><span v-if="row.targetDeviceId" class="detail-item"><ReferenceIcon :glyph="String.fromCodePoint(0xf0697)"/><router-link v-if="deviceLinks" :to="`/devices/${row.targetDeviceId}`">{{names.get(row.targetDeviceId)||row.targetDeviceId}}</router-link><span v-else>{{row.targetDeviceId}}</span></span><span v-if="row.properties" class="detail-item">{{row.properties}}</span></div></div></el-timeline-item></el-timeline>
 <div v-else class="unexpanded-result"><strong>{{labels[entry.result]}}</strong><span>{{entry.result==='SKIPPED'?'已跳过':entry.result==='BLOCKED'?'执行被阻止':entry.result==='PENDING'?'已触发一次执行':entry.result==='FAILED'?'执行失败，未记录具体节点原因。':'没有可确认的操作结果。'}}</span></div>
</div></template>
<style scoped>
.action-timeline{padding-left:8px;margin-top:12px}.timeline-dot{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#409eff;margin-left:-4px}.timeline-dot .reference-icon{font-size:16px;color:#fff}.timeline-dot.succeeded{background:#67c23a}.timeline-dot.failed{background:#f56c6c}.timeline-dot.pending,.timeline-dot.terminated{background:#e6a23c}.action-timeline :deep(.el-timeline-item__tail){left:10px}.action-timeline :deep(.el-timeline-item__content){padding-left:10px}.timeline-content{padding-top:2px}.timeline-header{display:flex;align-items:center;gap:8px;margin-bottom:4px}.header-type{font-weight:500;color:#333;font-size:14px}.header-time{color:#999;font-size:12px}.status-icon{display:flex;align-items:center;gap:4px;font-size:12px;color:#409eff;margin-left:auto;margin-right:20px}.status-icon .reference-icon{font-size:16px}.status-icon.succeeded{color:#67c23a}.status-icon.failed{color:#f56c6c}.status-icon.pending,.status-icon.terminated{color:#e6a23c}.timeline-action-detail{display:flex;flex-wrap:wrap;gap:12px;margin-top:4px}.detail-item{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:#666;background:#f0f9ff;padding:2px 8px;border-radius:4px;overflow-wrap:anywhere}.detail-item .reference-icon{font-size:14px;color:#409eff}.detail-item a{color:inherit;text-decoration:none}.detail-item a:hover{color:#409eff}.timeline-error{display:flex;align-items:flex-start;gap:6px;margin-top:6px;padding:8px 10px;background:#fef0f0;border-radius:4px;font-size:12px;color:#f56c6c;line-height:1.4}.description-error,.coverage-note{font-size:12px;color:#909399;line-height:20px;margin:8px 0}.unexpanded-result{display:flex;gap:10px;margin:12px 0;color:#666;font-size:13px}.unexpanded-result strong{font-weight:500}
</style>
